using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Identity;
namespace AcxiomCRM.Models;
public class ApplicationUser: IdentityUser { [MaxLength(120)] public string? FullName {get;set;} }
public class Customer { public int CustomerId {get;set;} [Required,MaxLength(120)] public string CustomerName {get;set;}=""; [Required,EmailAddress,MaxLength(160)] public string Email {get;set;}=""; [Required,Phone,MaxLength(20)] public string Phone {get;set;}=""; [MaxLength(120)] public string? CompanyName {get;set;} [MaxLength(100)] public string? City {get;set;} [MaxLength(100)] public string? State {get;set;} [MaxLength(30)] public string Status {get;set;}="Active"; public DateTime CreatedDate {get;set;}=DateTime.UtcNow; }
public class Lead { public int LeadId {get;set;} [Required,MaxLength(120)] public string LeadName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Phone] public string? Phone {get;set;} [MaxLength(120)] public string? CompanyName {get;set;} [MaxLength(50)] public string Source {get;set;}="Website"; [Required,MaxLength(30)] public string Status {get;set;}="New"; [Range(0,double.MaxValue)] public decimal ExpectedValue {get;set;} public DateTime CreatedDate {get;set;}=DateTime.UtcNow; }
public class Opportunity { public int OpportunityId {get;set;} [Required,MaxLength(150)] public string OpportunityName {get;set;}=""; public int? CustomerId {get;set;} [Range(0.01,double.MaxValue)] public decimal Amount {get;set;} [Range(0,100)] public int Probability {get;set;} [Required,MaxLength(30)] public string Stage {get;set;}="Qualification"; public DateTime ExpectedCloseDate {get;set;}=DateTime.Today.AddDays(30); [MaxLength(30)] public string Status {get;set;}="Open"; }
public class AuditLog { public int AuditLogId {get;set;} public string? UserId {get;set;} [Required] public string Action {get;set;}=""; [Required] public string EntityName {get;set;}=""; public string? RecordId {get;set;} public string? Details {get;set;} public DateTime CreatedDate {get;set;}=DateTime.UtcNow; public string? IpAddress {get;set;} }
